const expectedId = 1;
const expectedTitle = 'iPhone Galaxy +1';
const jsonData = pm.response.json();

pm.test('Status code is 200 OK', function () {
    pm.response.to.have.status(200);
});

pm.test('Response time is below 2000 ms', function () {
    pm.expect(pm.response.responseTime).to.be.below(2000);
});

pm.test('Response body is a JSON object', function () {
    pm.expect(jsonData).to.be.an('object');
    pm.expect(jsonData).to.not.be.null;
    pm.expect(Array.isArray(jsonData)).to.eql(false);
});

pm.test('Response contains the expected product keys', function () {
    pm.expect(jsonData).to.have.all.keys(
        'id',
        'title',
        'price',
        'discountPercentage',
        'stock',
        'rating',
        'images',
        'thumbnail',
        'description',
        'brand',
        'category'
    );
});

pm.test('Product id is 1', function () {
    pm.expect(jsonData.id).to.eql(expectedId);
});

pm.test('Title was updated to the requested value', function () {
    pm.expect(jsonData.title).to.eql(expectedTitle);
});

pm.test('Numeric product fields have number values', function () {
    pm.expect(jsonData.price).to.be.a('number');
    pm.expect(jsonData.discountPercentage).to.be.a('number');
    pm.expect(jsonData.stock).to.be.a('number');
    pm.expect(jsonData.rating).to.be.a('number');
});

pm.test('Required string fields are present and non-empty', function () {
    ['description', 'brand', 'category', 'thumbnail'].forEach((field) => {
        pm.expect(jsonData[field], `${field} should exist`).to.exist;
        pm.expect(jsonData[field], `${field} should be a string`).to.be.a('string');
        pm.expect(jsonData[field].trim(), `${field} should not be empty`).to.have.length.above(0);
    });
});

pm.test('Images is a non-empty array of strings', function () {
    pm.expect(jsonData.images).to.be.an('array').that.is.not.empty;
    jsonData.images.forEach((image, index) => {
        pm.expect(image, `images[${index}] should be a string`).to.be.a('string');
        pm.expect(image.trim(), `images[${index}] should not be empty`).to.have.length.above(0);
    });
});

pm.test('PATCH response reflects the requested update payload', function () {
    const requestBody = pm.request.body && pm.request.body.raw ? JSON.parse(pm.request.body.raw) : {};
    pm.expect(requestBody).to.have.property('title');
    pm.expect(jsonData.title).to.eql(requestBody.title);
});
